<source_code>
// practice with rainboy
import java.io.*;
import java.util.*;

public class CF1096G {
	static final int MD = 998244353;
	static long[] ww, ww_;
	static long power(int a, int k) {
		if (k == 0)
			return 1;
		long p = power(a, k / 2);
		p = p * p % MD;
		if (k % 2 == 1)
			p = p * a % MD;
		return p;
	}
	static void init() {
		ww = new long[21];
		ww_ = new long[21];
		for (int h = 0; h <= 20; h++) {
			ww[h] = power(3, MD - 1 >> h);
			ww_[h] = power(3, MD - 1 - (MD - 1 >> h));
		}
	}
	static void ntt(int[] aa, int n, boolean inverse) {
		for (int i = 1, j = 0; i < n; i++) {
			int b = n;
			do
				j ^= b >>= 1;
			while ((j & b) == 0);
			if (i < j) {
				int tmp = aa[i]; aa[i] = aa[j]; aa[j] = tmp;
			}
		}
		for (int h = 0, b; (b = 1 << h) < n; h++) {
			long w_ = inverse ? ww_[h + 1] : ww[h + 1];
			for (int i = 0; i < n; i += b * 2) {
				long w = 1;
				for (int j = 0; j < b; j++) {
					int l = i + j, r = l + b;
					long u = aa[l], v = aa[r] * w;
					aa[l] = (int) ((u + v) % MD);
					aa[r] = (int) ((u - v) % MD);
					w = w * w_ % MD;
				}
			}
		}
	}
	public static void main(String[] args) throws IOException {
		init();
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(br.readLine());
		int n = Integer.parseInt(st.nextToken()) / 2;
		int k = Integer.parseInt(st.nextToken());
		int n_ = 1;
		while (n_ < n * 9 + 1)
			n_ *= 2;
		int[] aa = new int[n_];
		st = new StringTokenizer(br.readLine());
		while (k-- > 0) {
			int d = Integer.parseInt(st.nextToken());
			aa[d] = 1;
		}
		ntt(aa, n_, false);
		for (int i = 0; i < n_; i++)
			aa[i] = (int) power(aa[i], n);
		ntt(aa, n_, true);
		long v = power(n_, MD - 2);
		for (int i = 0; i < n_; i++) {
			aa[i] = (int) (aa[i] * v % MD);
			if (aa[i] < 0)
				aa[i] += MD;
		}
		long ans = 0;
		for (int i = 0; i <= n * 9; i++) {
			long a = aa[i];
			ans = (ans + a * a) % MD;
		}
		System.out.println(ans);
	}
}

